package com.weather.system.config;
import org.springframework.stereotype.Component; import org.springframework.web.servlet.HandlerInterceptor; import javax.servlet.http.*; import io.jsonwebtoken.Claims;
@Component public class AuthInterceptor implements HandlerInterceptor { private final JwtUtil jwt; public AuthInterceptor(JwtUtil jwt){this.jwt=jwt;} public boolean preHandle(HttpServletRequest r,HttpServletResponse s,Object h)throws Exception { if(r.getRequestURI().startsWith("/api/auth/")) return true; String v=r.getHeader("Authorization"); if(v==null||!v.startsWith("Bearer ")){s.setStatus(401); return false;} try{Claims c=jwt.parse(v.substring(7)); r.setAttribute("username",c.getSubject()); r.setAttribute("role",c.get("role",String.class)); return true;}catch(Exception e){s.setStatus(401); return false;} } }
